(()=>{const carousel=document.querySelector('.category-carousel');if(!carousel)return;const update=()=>{const bounds=carousel.getBoundingClientRect();const top=bounds.top+window.scrollY;const bottom=bounds.bottom+window.scrollY;const style=document.body.style;style.setProperty('--wash-height',`${Math.ceil(bottom+32)}px`);style.setProperty('--fade-start',`${Math.max(0,Math.floor(top-54))}px`);style.setProperty('--fade-middle',`${Math.floor(top+(bottom-top)*.48)}px`)};update();window.addEventListener('load',update,{once:true});window.addEventListener('resize',update,{passive:true});if('ResizeObserver'in window)new ResizeObserver(update).observe(carousel)})();
